    claimBooster: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Booster ouvert, cartes ajoutées à la collection */
            201: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "id": "3f1c2a9e-5b7d-4c1e-9a2b-1d2e3f4a5b6c",
                     *       "claimDate": "2026-11-10",
                     *       "openedAt": "2026-11-10T08:14:03Z",
                     *       "cards": [
                     *         {
                     *           "creature": {
                     *             "id": "0b6f2c1e-1a2b-4c3d-8e9f-0a1b2c3d4e5f",
                     *             "name": "Moussou",
                     *             "family": {
                     *               "code": "NATURE",
                     *               "label": "Nature"
                     *             },
                     *             "rarity": {
                     *               "code": "COMMON",
                     *               "label": "Commun"
                     *             },
                     *             "imageUrl": "https://app.creatura.fr/images/moussou.webp"
                     *           },
                     *           "isNew": false
                     *         },
                     *         {
                     *           "creature": {
                     *             "id": "7c8d9e0f-1a2b-4c3d-9e8f-7a6b5c4d3e2f",
                     *             "name": "Cristille",
                     *             "family": {
                     *               "code": "CRISTAL",
                     *               "label": "Cristal"
                     *             },
                     *             "rarity": {
                     *               "code": "RARE",
                     *               "label": "Rare"
                     *             },
                     *             "imageUrl": "https://app.creatura.fr/images/cristille.webp"
                     *           },
                     *           "isNew": true
                     *         }
                     *       ]
                     *     }
                     */
                    "application/json": components["schemas"]["Booster"];
                };
            };
            401: components["responses"]["Unauthorized"];
            /** @description Booster du jour déjà réclamé (`BOOSTER_ALREADY_CLAIMED`). Aucune carte n'est donnée ; `boosterId` désigne le booster déjà ouvert. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "type": "https://app.creatura.fr/problems/booster-already-claimed",
                     *       "title": "Booster déjà réclamé",
                     *       "status": 409,
                     *       "code": "BOOSTER_ALREADY_CLAIMED",
                     *       "detail": "Le booster du 2026-11-10 a déjà été ouvert. Prochain booster à partir de minuit (heure de Paris).",
                     *       "boosterId": "3f1c2a9e-5b7d-4c1e-9a2b-1d2e3f4a5b6c"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
